const require_index = require("../useThrottleFn/index.js");
let react = require("react");
//#region src/useThrottle/index.ts
const useThrottle = (value, wait, options) => {
	const [throttled, setThrottled] = (0, react.useState)(value);
	const { run } = require_index.useThrottleFn(() => {
		setThrottled(value);
	}, wait, options);
	(0, react.useEffect)(() => {
		run();
	}, [run, value]);
	return throttled;
};
//#endregion
exports.useThrottle = useThrottle;
